const code2 = "\nWe can see that this is a mix of HTML, JavaScript, and CSS. Later, this component will be the container for our chat messages, but for now, it is just a purple box with \"Chat Content\" written in it. The script portion merely exports the component name for right now, the `<template>` contains our HTML with a basic `<div>` element that will hold our content, and the style portion applies some basic styles to our `<div>` element by referencing its class name. We are using the `scoped` attribute to ensure that these styles only apply to this component. This is a handy feature of Vue.js because it allows us to use the same class names in different components without worrying about them conflicting with each other.\n\nNext, let's create one more component which will be the container for the input row at the bottom of the chat window. Create a new file called `InputRow.vue` and place the following code in it.\n\n```html[InputRow.vue]\n<script>\n  export default {\n    name: \"InputRow\",\n    components: {},\n  };\n</" + "script>\n\n<template>\n  <div class=\"input-row\">\n    <h1>Input Row</h1>\n  </div>\n</template>\n\n<style scoped>\n  .input-row {\n    background-color: #f6db99;\n    border-radius: 10px;\n    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n    height: 100%;\n    padding: 1rem;\n    width: 100%;\n  }\n</style>\n";
const code3 = "components/\n├── ChatContent.vue\n└── InputRow.vue\n";
const code4 = "<script setup>\n  import ChatContent from \"./components/ChatContent.vue\";\n  import InputRow from \"./components/InputRow.vue\";\n</" + "script>\n\n<template>\n  <div class=\"app\">\n    <ChatContent />\n    <InputRow />\n  </div>\n</template>\n\n<style scoped></style>\n";
const code5 = "<script>\n  export default {\n    name: \"ChatBubble\",\n    components: {},\n  };\n</" + "script>\n\n<template>\n  <div class=\"chat-bubble\">\n    <div class=\"chat-bubble-content\">Test</div>\n  </div>\n</template>\n\n<style scoped>\n  .chat-bubble {\n    background-color: #f6f8d0;\n    margin-bottom: 10px;\n  }\n</style>\n";
const code6 = "<script>\n  import ChatBubble from \"./ChatBubble.vue\";\n\n  export default {\n    name: \"ChatContent\",\n    components: {\n      ChatBubble,\n    },\n  };\n</" + "script>\n\n<template>\n  <div class=\"chat-content\">\n    <ChatBubble />\n    <ChatBubble />\n    <ChatBubble />\n    <ChatBubble />\n    <ChatBubble />\n  </div>\n</template>\n\n<style scoped>\n  .chat-content {\n    background-color: #eda9f9;\n    border-radius: 10px;\n    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n    height: 100%;\n    padding: 1rem;\n    width: 100%;\n  }\n</style>\n";
const code7 = "<script>\n  export default {\n    components: {},\n  };\n</" + "script>\n\n<template>\n  <div class=\"input-row\">\n    <textarea></textarea>\n    <button>Send</button>\n  </div>\n</template>\n\n<style scoped>\n  .input-row {\n    display: flex;\n    background-color: #f6db99;\n    border-radius: 10px;\n    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n    padding: 1rem;\n    width: 100%;\n  }\n</style>\n";
const code8 = "<script>\n  export default {\n    name: \"ChatBubble\",\n    props: {\n      message: {\n        type: Object,\n        required: true,\n      },\n    },\n  };\n</" + "script>\n\n<template>\n  <div :class=\"['chat-bubble', message.role]\">\n    <div class=\"chat-bubble-avatar\">{{ message.role[0].toUpperCase() }}</div>\n    <div class=\"chat-bubble-content\">{{ message.content }}</div>\n  </div>\n</template>\n\n<style scoped>\n  .chat-bubble {\n    display: flex;\n    align-items: center;\n    flex-direction: row;\n    margin-bottom: 10px;\n  }\n\n  .chat-bubble.assistant {\n    flex-direction: row-reverse;\n  }\n\n  .chat-bubble-avatar {\n    background-color: #e1e1e1;\n    border-radius: 50%;\n    color: #000;\n    font-weight: bold;\n    height: 40px;\n    line-height: 40px;\n    margin-right: 10px;\n    text-align: center;\n    width: 40px;\n    margin: 0px 10px;\n  }\n\n  .chat-bubble-content {\n    border-radius: 10px;\n    padding: 10px;\n  }\n\n  .user .chat-bubble-content {\n    background-color: #f6db99;\n  }\n\n  .assistant .chat-bubble-content {\n    background-color: #f6f8d0;\n    text-align: right;\n  }\n</style>\n";
const code9 = "<script>\n  import ChatBubble from \"./ChatBubble.vue\";\n\n  export default {\n    name: \"ChatContent\",\n    components: {\n      ChatBubble,\n    },\n    data() {\n      return {\n        messages: [\n          { role: \"user\", content: \"Hello\" },\n          { role: \"assistant\", content: \"Hi, how are you?\" },\n          { role: \"user\", content: \"I'm fine, thanks.\" },\n          { role: \"assistant\", content: \"Good to hear.\" },\n          { role: \"user\", content: \"Bye.\" },\n        ],\n      };\n    },\n  };\n</" + "script>\n\n<template>\n  <div class=\"chat-content\">\n    <ChatBubble\n      v-for=\"(message, index) in messages\"\n      :key=\"index\"\n      :message=\"message\"\n    />\n  </div>\n</template>\n\n<style scoped>\n  .chat-content {\n    background-color: #eda9f9;\n    border-radius: 10px;\n    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n    height: 100%;\n    padding: 1rem;\n    width: 100%;\n  }\n</style>\n";
const code10 = "@import \"./base.css\";\n";
const code11 = ".app {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  height: 100vh;\n  width: 100vw;\n  margin: 0;\n  padding: 0;\n}\n\n.app-content {\n  display: flex;\n  flex-direction: column;\n  flex-grow: 1;\n  padding: 1rem;\n  width: 100%;\n  max-width: 1000px;\n  overflow: auto;\n}\n";
const code12 = ".chat-content {\n  background-color: #f4f8ff;\n  border-radius: 10px;\n  box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n  height: 100%;\n  padding: 1rem;\n  width: 100%;\n  margin-bottom: 10px;\n  overflow: auto;\n}\n";
